#include "environment/dsp/BedScheduler.h"
#include <cmath>
#include <iostream>
#include <stdexcept>
int main(){try{lsse::environment::BedScheduler a,b;a.prepare(48000,91);b.prepare(48000,91);double energy=0,weather=0,events=0;for(std::uint64_t i=0;i<48000;++i){if(a.sampleAt(i,false,1)!=0)throw std::runtime_error("generator-off silence failed");const auto x=a.sampleAt(i,true,1),y=b.sampleAt(i,true,1);if(x!=y||!std::isfinite(x))throw std::runtime_error("keyed timeline mismatch");const auto layers=a.layersAt(i,true,.9f,.8f,.6f),copy=b.layersAt(i,true,.9f,.8f,.6f);if(layers.bed!=copy.bed||layers.weather!=copy.weather||layers.events!=copy.events)throw std::runtime_error("layer streams were not deterministic");energy+=layers.bed*layers.bed;weather+=layers.weather*layers.weather;events+=layers.events*layers.events;}if(energy<=0||weather<=0||events<=0)throw std::runtime_error("environment layer was silent");const auto off=a.layersAt(0,false,1,1,1);if(off.bed!=0||off.weather!=0||off.events!=0)throw std::runtime_error("layer silence policy failed");std::cout<<"ENVIRONMENT scheduler tests passed\n";return 0;}catch(const std::exception&x){std::cerr<<x.what()<<'\n';return 1;}}
